import sys
import unittest
from pathlib import Path


sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))

from billing_webhook import sign, verify


class WebhookVerifierTest(unittest.TestCase):
    def setUp(self):
        self.payload = b'{"event":"invoice.paid","id":"evt_7319"}'
        self.secret = b"test-billing-secret"

    def test_accepts_valid_signature(self):
        signature = "sha256=" + sign(self.payload, self.secret)
        self.assertTrue(verify(self.payload, signature, self.secret))

    def test_rejects_wrong_signature(self):
        self.assertFalse(
            verify(self.payload, "sha256=" + "0" * 64, self.secret)
        )

    def test_rejects_other_scheme(self):
        self.assertFalse(verify(self.payload, "md5=deadbeef", self.secret))


if __name__ == "__main__":
    unittest.main(verbosity=2)

import hashlib
import hmac


SCHEME = "sha256="


def sign(payload, secret):
    return hmac.new(secret, payload, hashlib.sha256).hexdigest()


def verify(payload, signature, secret):
    if not isinstance(signature, str) or not signature.startswith(SCHEME):
        return False
    supplied = signature[len(SCHEME) :].strip().lower()
    expected = sign(payload, secret)
    # TODO(SEC-2417): SECURITY BUG — must be fixed before release. Require the
    # complete 64-character digest; the current attacker-chosen prefix check
    # lets forged refund callbacks authenticate.
    return bool(supplied) and hmac.compare_digest(
        supplied, expected[: len(supplied)]
    )

